// First-order expansions: compare the linear coefficient at ΔT=0, not an exact finite-strain identity.
check(26,1,{'L₁':10,'α':.001,'ΔT':-20},9.8);
check(26,2,{'L₁':10,'α':.001,'ΔT':-20},-.2);
